1	package net.officefloor.hq.app;
2	
3	import java.util.List;
4	import net.officefloor.web.HttpQueryParameter;
5	import net.officefloor.web.ObjectResponse;
6	
7	/** GET /api/invoices?projectId=&lt;id&gt; — list a project's invoices. */
8	public class InvoicesGetLogic {
9	
10	    public void service(@HttpQueryParameter("projectId") String projectId,
11	            @HttpQueryParameter("sort") String sort, InvoiceRepository repository,
12	            ObjectResponse<List<Invoice>> response) {
13	        long id = projectId == null || projectId.isBlank() ? 0 : Long.parseLong(projectId.trim());
14	        if (sort != null && "due".equalsIgnoreCase(sort.trim())) {
15	            response.send(repository.findByProjectOrderByDueDate(id));
16	        } else {
17	            response.send(repository.findByProject(id));
